def findTargetSumWays(nums: list[int], target: int) -> int:
    memo = {}
    def dfs(idx, curr):
        if idx == len(nums):
            return 1 if curr == target else 0
        state = (idx, curr)
        if state in memo: return memo[state]
        ans = dfs(idx + 1, curr + nums[idx]) + dfs(idx + 1, curr - nums[idx])
        memo[state] = ans
        return ans
    return dfs(0, 0)

